const items = $input.all();

const REASON_LABELS = {
  ocr_failed: 'OCR fehlgeschlagen',
  no_company_match: 'Keine Acribo-Gesellschaft erkannt',
  no_valid_attachment: 'Kein PDF/P7M-Anhang – nicht weitergeleitet',
  p7m_extract_failed: 'P7M-Entpacken fehlgeschlagen',
  decrypt_failed: 'Entschlüsselung fehlgeschlagen',
};

function toRow(j) {
  return {
    'Anhang-ID': j.attachment_id || j.mail_id || '',
    'Mail-ID': j.mail_id || '',
    'Dateiname': j.file_name || '',
    'Absender': j.from || '',
    'Betreff': j.subject || '',
    'Weiterleitung an': j.forward_to || '',
    'OCR-Status': j.ocr_status || '',
    'Fallback-Grund': REASON_LABELS[j.fallback_reason] || j.fallback_reason || '',
    'Erstellt am': j.createdAt || '',
  };
}

function summaryLine(label, value) {
  return { json: { 'Anhang-ID': label, 'Mail-ID': String(value ?? 0) } };
}

const detailRows = items.map((item) => ({ json: toRow(item.json) }));

const completed = items.filter((i) => i.json.ocr_status !== 'processing');
const successful = completed.filter(
  (i) => i.json.ocr_status === 'success' && !i.json.fallback_reason
);
const fallbackItems = completed.filter(
  (i) =>
    i.json.fallback_reason ||
    i.json.forward_to === 'fi@acribo.com' ||
    ['failed', 'error'].includes(i.json.ocr_status)
);
const uniqueMails = new Set(items.map((i) => i.json.mail_id).filter(Boolean));
const processing = items.filter((i) => i.json.ocr_status === 'processing');
const skipped = items.filter((i) => i.json.ocr_status === 'skipped' || i.json.fallback_reason === 'no_valid_attachment');

const summary = [
  { json: { 'Anhang-ID': '=== ZUSAMMENFASSUNG ===' } },
  summaryLine('Anhänge gesamt', items.length),
  summaryLine('E-Mails gesamt (unique)', uniqueMails.size),
  summaryLine('Erfolgreich weitergeleitet', successful.length),
  summaryLine('Fallback / Fehler', fallbackItems.length),
  summaryLine('Noch in Verarbeitung', processing.length),
  summaryLine('Ohne Anhang übersprungen', skipped.length),
  { json: { 'Anhang-ID': '=== PRO ZIEL-POSTFACH ===' } },
];

const byForward = {};
completed.forEach((i) => {
  const key = i.json.forward_to || '(leer)';
  byForward[key] = (byForward[key] || 0) + 1;
});
Object.entries(byForward)
  .sort((a, b) => b[1] - a[1])
  .forEach(([key, count]) => summary.push(summaryLine(key, count)));

summary.push({ json: { 'Anhang-ID': '=== FALLBACK-GRÜNDE ===' } });
const byReason = {};
completed
  .filter((i) => i.json.fallback_reason)
  .forEach((i) => {
    const key = i.json.fallback_reason;
    byReason[key] = (byReason[key] || 0) + 1;
  });
if (Object.keys(byReason).length === 0) {
  summary.push(summaryLine('(keine)', 0));
} else {
  Object.entries(byReason)
    .sort((a, b) => b[1] - a[1])
    .forEach(([key, count]) =>
      summary.push(summaryLine(REASON_LABELS[key] || key, count))
    );
}

return [...detailRows, { json: {} }, ...summary];

